import type {Role} from '@github-ui/role-assignments/types/role-assignments'
import type {Actor, AssigneeType, RoleStatus, Team} from '../enterprise-role-assignments-types'

export const ROLE_STATUS_MESSAGES = {
  ESM_DISABLED_FOR_USER:
    'Unavailable: roles with repository or organization permissions can only be assigned to teams.',
  ESM_DISABLED_FOR_BUSINESS_TEAMS: 'Unavailable: Enterprise Teams organization limit exceeded',
} as const

export function isEsm(role: Role): boolean {
  return role.name === 'Enterprise Security Manager' && role.octicon === 'shield-lock'
}

export function showEsmWarning(selectedRole: Role | null, assignee: Actor | null): assignee is Team {
  if (!selectedRole || !assignee || assignee.type !== 'businessteam') return false

  const orgSelectionType = (assignee as Team).orgSelectionType
  return isEsm(selectedRole) && orgSelectionType !== undefined && orgSelectionType !== 'all'
}

export function esmStatus(
  assigneeType: AssigneeType | undefined,
  enterpriseTeamOrgAssignmentLimitExceeded: boolean,
): RoleStatus {
  if (enterpriseTeamOrgAssignmentLimitExceeded) {
    return {
      status: 'disabled',
      statusText: ROLE_STATUS_MESSAGES.ESM_DISABLED_FOR_BUSINESS_TEAMS,
    }
  } else if (assigneeType === 'user') {
    return {
      status: 'disabled',
      statusText: ROLE_STATUS_MESSAGES.ESM_DISABLED_FOR_USER,
    }
  }

  return {status: 'enabled'}
}
