import type {AvatarOrg, Role} from '@github-ui/role-assignments/types/role-assignments'
import type {RoleStatus} from '../enterprise-role-assignments-types'
import {Radio, Text, Link as PrimerLink, IconButton, Truncate} from '@primer/react'
import {Link} from '@github-ui/react-core/link'
import {useRef, useState} from 'react'
import {isEsm} from '../utils/role-utils'
import {RoleAvatarSpread} from '@github-ui/role-assignments/role-avatar-spread'
import {testIdProps} from '@github-ui/test-id-props'
import {InfoIcon} from '@primer/octicons-react'
import {enterprisePath} from '@github-ui/paths'
import getRoleIcon from '@github-ui/role-assignments/utils/icon-map'
import styles from './NewRoleAssignmentRadio.module.css'
import {RoleFgpsDialog} from '@github-ui/role-assignments/role-fgps-dialog'
import {InlineMessage} from '@primer/react/experimental'
import {clsx} from 'clsx'

export interface NewRoleAssignmentRadioProps {
  role: Role
  roleStatus: RoleStatus | null
  checked: boolean
  avatarOrgs?: AvatarOrg[]
}

export function NewRoleAssignmentRadio({role, roleStatus, checked, avatarOrgs}: NewRoleAssignmentRadioProps) {
  const [showFgpMetadata, setShowFgpMetadata] = useState(false)
  const hasDescriptionContent = role.description || role.enterpriseOwner
  const isDisabled = roleStatus?.status === 'disabled'
  const isEsmRole = isEsm(role)
  const avatarOrgAvatarURLs = avatarOrgs?.map(org => org.avatarURL) ?? []
  const id = `role-${role.id}`
  const infoButtonRef = useRef<HTMLButtonElement>(null)

  const esmAccessText = 'Grants access to all organizations'
  const descriptionTitle = [
    role.enterpriseOwner && `Role managed by ${role.enterpriseOwner.name}`,
    isEsmRole && esmAccessText,
    role.description,
  ]
    .filter(Boolean)
    .join(' • ')

  return (
    <div className={styles.radioItem} {...testIdProps(`role-assignment-list-radio-${role.name}`)}>
      <div className={styles.content}>
        <div className={styles.mainContent}>
          <div className={styles.title}>
            <label className={clsx(styles.label, isDisabled && styles.disabled)}>
              <Radio
                value={role.id.toString()}
                aria-describedby={hasDescriptionContent ? `${id}-description` : undefined}
                {...testIdProps(`role-assignment-list-item-${role.name}`)}
                name="role-assignment-radio-group"
                disabled={isDisabled}
                className={styles.radio}
                checked={checked}
              />
              <span className={styles.leadingVisual} {...testIdProps('role-icon')}>
                {getRoleIcon(role.octicon)}
              </span>
              <Text weight="semibold">{role.name}</Text>
            </label>
          </div>
          {hasDescriptionContent && (
            <div className={styles.subtitle} id={`${id}-description`}>
              <div className={styles.description} {...testIdProps('role-description')}>
                {isEsmRole && <RoleAvatarSpread avatarURLs={avatarOrgAvatarURLs} />}
                <Truncate inline maxWidth="100%" title={descriptionTitle}>
                  {role.enterpriseOwner && <EnterpriseOwnedRoleContent {...role.enterpriseOwner} />}
                  {role.enterpriseOwner && role.description && <span>{' • '}</span>}
                  {isEsmRole && (
                    <>
                      <span className="fgColor-default">{esmAccessText}</span>
                      <span>{' • '}</span>
                    </>
                  )}
                  {role.description && <span>{role.description}</span>}
                </Truncate>
              </div>
              {isDisabled && (
                <InlineMessage size="small" variant="warning" {...testIdProps('role-warning')}>
                  {roleStatus.statusText}
                </InlineMessage>
              )}
            </div>
          )}
        </div>
        <IconButton
          ref={infoButtonRef}
          icon={InfoIcon}
          variant="invisible"
          aria-label={`Info about ${role.name}`}
          onClick={() => setShowFgpMetadata(true)}
          {...testIdProps('role-info-button')}
        />
      </div>

      <RoleFgpsDialog
        role={role}
        show={showFgpMetadata}
        returnFocusRef={infoButtonRef}
        onClose={() => {
          setShowFgpMetadata(false)
        }}
      />
    </div>
  )
}

function EnterpriseOwnedRoleContent(props: {name: string; slug: string}) {
  return (
    <span {...testIdProps('enterprise-owned-role')}>
      Role managed by{' '}
      <PrimerLink as={Link} to={enterprisePath({slug: props.slug})} target="_blank" inline>
        {props.name}
      </PrimerLink>
    </span>
  )
}
