import {Filter} from '@github-ui/filter'
import type {Role} from '@github-ui/role-assignments/types/role-assignments'
import {testIdProps} from '@github-ui/test-id-props'
import {createAssignmentFilterProviders} from '../utils/filter-utils'
import type {FilterQuery} from '@github-ui/filter-core'

interface RoleAssignmentsFilterProps {
  placeholderText: string
  filterValue: string
  onChange: (value: string) => void
  onSubmit: (request: FilterQuery) => void
  availableRoles?: Role[]
}

export function RoleAssignmentsFilter({
  placeholderText,
  filterValue,
  onChange,
  onSubmit,
  availableRoles,
}: RoleAssignmentsFilterProps) {
  const providers = createAssignmentFilterProviders(availableRoles)

  return (
    <Filter
      variant="input"
      filterValue={filterValue}
      providers={providers}
      onSubmit={onSubmit}
      onChange={onChange}
      id="role-assignments-filter"
      {...testIdProps('role-assignments-filter')}
      label={placeholderText}
      placeholder={placeholderText}
    />
  )
}
